// Monolith: an in-process function call
function placeOrder(order) {
  const result = chargeCard(order.card, order.amount); // can't fail from a dropped connection
  return result;
}

// Microservices: the same logic is now a network call
async function placeOrder(order) {
  const response = await fetch('https://payment-service/charge', {
    method: 'POST',
    body: JSON.stringify({ card: order.card, amount: order.amount }),
    timeout: 3000, // now you must think about timeouts
  });
  if (!response.ok) {
    // and about retries, and what "the service didn't answer" even means
    throw new Error('payment service unavailable, order not confirmed');
  }
  return response.json();
}

