// orders-service: after payment succeeds, tell the rest of the system
async function confirmOrder(order) {
  await paymentClient.charge(order.card, order.amount);
  await eventBus.publish('order.confirmed', {
    orderId: order.id,
    userId: order.userId,
    total: order.amount,
  });
  // cart service listens for this event and clears the user's cart,
  // instead of orders reaching directly into cart's database
}

